SELECT

FROM RwaBalancesTransHistory a WHERE 1 = 1

    AND a.userId = #{userId}


    AND a.currency = #{currency}


    AND a.type = #{type}


    AND a.beforeBal = #{beforeBal}


    AND a.changeAmt = #{changeAmt}


    AND a.afterBal = #{afterBal}


    AND a.businessId = #{businessId}


    AND a.fromAcct = #{fromAcct}


    AND a.toAcct = #{toAcct}


    AND a.state = #{state}


    AND a.transDesc = #{transDesc}


    AND a.remark = #{remark}


    AND a.createTime = #{createTime}

limit 1

SELECT

FROM RwaBalancesTransHistory a WHERE 1 = 1

    AND a.userId = #{userId}


    AND a.currency LIKE CONCAT('%',#{currency}, '%')


    AND a.type LIKE CONCAT('%',#{type}, '%')


    AND a.beforeBal = #{beforeBal}


    AND a.changeAmt = #{changeAmt}


    AND a.afterBal = #{afterBal}


    AND a.businessId LIKE CONCAT('%',#{businessId}, '%')


    AND a.fromAcct LIKE CONCAT('%',#{fromAcct}, '%')


    AND a.toAcct LIKE CONCAT('%',#{toAcct}, '%')


    AND a.state LIKE CONCAT('%',#{state}, '%')


    AND a.transDesc LIKE CONCAT('%',#{transDesc}, '%')


    AND a.remark LIKE CONCAT('%',#{remark}, '%')


    AND a.createTime = #{createTime}
